def forward(
    message_id,
    to,
    attach=None,
    bcc=None,
    body_=None,
    cc=None,
    draft=None,
    from_=None,
    html=None,
    no_original_attachments=None,
    test=False,
):
    """
    [Helper] Forward a message to new recipients

    Options:

    * ``message_id`` (required value): Gmail message ID to forward
    * ``to`` (required value): Recipient email address(es), comma-separated
    * ``attach`` (optional value): Attach a file (can be specified multiple times)
    * ``bcc`` (optional value): BCC email address(es), comma-separated
    * ``body_`` (optional value): Optional note to include above the forwarded message (plain text, or HTML with --html)
    * ``cc`` (optional value): CC email address(es), comma-separated
    * ``draft`` (optional flag): Save as draft instead of sending
    * ``from_`` (optional value): Sender address (for send-as/alias; omit to use account default)
    * ``html`` (optional flag): Treat --body as HTML content (default is plain text)
    * ``no_original_attachments`` (optional flag): Do not include file attachments from the original message (inline images in --html mode are preserved)

    CLI Example:

    .. code-block:: bash

        salt '*' gsuite_gmail.forward
    """
    return _gws.run_helper(
        __opts__,
        __pillar__,
        "gmail",
        "+forward",
        flags={
            "message-id": message_id,
            "to": to,
            "attach": attach,
            "bcc": bcc,
            "body": body_,
            "cc": cc,
            "from": from_,
        },
        switches={
            "draft": draft,
            "html": html,
            "no-original-attachments": no_original_attachments,
        },
        test=test,
    )


