def watch(
    cleanup=None,
    label_ids=None,
    max_messages=None,
    msg_format=None,
    once=None,
    output_dir=None,
    poll_interval=None,
    project=None,
    subscription=None,
    topic=None,
    test=False,
):
    """
    [Helper] Watch for new emails and stream them as NDJSON

    Options:

    * ``cleanup`` (optional flag): Delete created Pub/Sub resources on exit
    * ``label_ids`` (optional value): Comma-separated Gmail label IDs to filter (e.g., INBOX,UNREAD)
    * ``max_messages`` (optional value): Max messages per pull batch [default: 10]
    * ``msg_format`` (optional value): Gmail message format: full, metadata, minimal, raw [default: full] [possible values: full, metadata, minimal, raw]
    * ``once`` (optional flag): Pull once and exit
    * ``output_dir`` (optional value): Write each message to a separate JSON file in this directory
    * ``poll_interval`` (optional value): Seconds between pulls [default: 5]
    * ``project`` (optional value): GCP project ID for Pub/Sub resources
    * ``subscription`` (optional value): Existing Pub/Sub subscription name (skip setup)
    * ``topic`` (optional value): Existing Pub/Sub topic with Gmail push permission already granted

    CLI Example:

    .. code-block:: bash

        salt '*' gsuite_gmail.watch
    """
    return _gws.run_helper(
        __opts__,
        __pillar__,
        "gmail",
        "+watch",
        flags={
            "label-ids": label_ids,
            "max-messages": max_messages,
            "msg-format": msg_format,
            "output-dir": output_dir,
            "poll-interval": poll_interval,
            "project": project,
            "subscription": subscription,
            "topic": topic,
        },
        switches={
            "cleanup": cleanup,
            "once": once,
        },
        test=test,
    )
